-- The zone names come from the client's own AreaTable.dbc (Locales/zhCN/Areas.lua):
-- 2105 English->Chinese pairs generated by tools/dbc_areas.py. The client here is
-- enUS, so it hands out English zone and subzone names even when the diary reads
-- Chinese; the generated table is what turns them over where they are drawn.

local T = ...
local Section, Check, Eq = T.Section, T.Check, T.Eq

-- This client reports enUS; the diary reads Chinese only when that is the choice.
local saved = rawget(_G, "SocialDiaryDB")
_G.SocialDiaryDB = { settings = { language = "zhCN" } }
local ns = T.Load()
_G.SocialDiaryDB = saved
Eq(ns.Locale.id, "zhCN", "the diary is not reading Chinese")

local CoA = ns.CoA
Check(CoA and CoA.zhName, "the name lookup is not installed")

Section("a subzone the client only knows in English")

Eq(CoA.zhName("Blackwater Cove"), "黑水湾", "a name from the client's area table is not translated")
Eq(ns.ZoneShown("Blackwater Cove"), "黑水湾", "the display path does not translate the name")
Eq(CoA.zhName("Nowhere At All"), "Nowhere At All", "an unknown name was changed")
Eq(CoA.enName("黑水湾"), "Blackwater Cove", "the reverse table has no entry")

Section("the hand-written table still wins")

Eq(CoA.zhName("Stormwind City"), "暴风城", "a curated name was overwritten by the generated one")
-- Names even the client's own DBCs cannot supply (see tests/dbc_names.lua for
-- the ones they can). The list is a handful now, and every name still in it must
-- really be untranslated: a translated name here means a lookup we forgot.
Check(CoA.todoNames and #CoA.todoNames < 10,
      "the list of names left in English grew back: " .. tostring(CoA.todoNames and #CoA.todoNames))
for _, name in ipairs(CoA.todoNames or {}) do
    Eq(CoA.zhName(name), name, "a name listed as English is actually translated: " .. name)
end

Section("the whole area table is in")

local count = 0
for _ in pairs(CoA.zhNames) do count = count + 1 end
Check(count > 2000, "the generated area names are not loaded (" .. count .. ")")
